5.No Hay Dios Tan Grande Como Tu
// No Hay Dios Tan Grande Como Tu
  No Lo Hay, No Lo Hay //
// No Hay Dios 
  Que Pueda Hacer Las Obras
  Como Las Que Haces Tu //
// No Es Con Espada, Ni Con Ejercito
  Mas Con Tu Santo Espíritu //
/// Y Esta Iglesia, Se Moverá ///
Mas Con Tu Santo Espíritu

9.  Sin Santidad 
// Sin Santidad 
  Nadie Vera Al Señor //
// Pero Yo Se, Pero Yo Se
  Que Le Veré, Que Le Veré
  Y Con Su Espíritu Me Santificare //

13.  Envía Tu Poder
// Envía Tu Poder //
Envía Tu Poder Señor
// Queremos Mas Poder //
Queremos Mas Poder Señor

14.  Preparate Para Que Sientas
/// Preparate Para Que Sientas ///
El Espíritu De Dios
/// Y Dejalo Que Se Mueva ///
Dentro De Tu Corazón

15.  Ya Hemos Orado
// Ya Hemos Orado Y Ha Bajado
  El Poder De Dios //
// Oh Gloria A Dios //
Ya Hemos Orado Y Ha Bajado 
El Poder De Dios

30.  En El Principio
//En El Principio El Espíritu De Dios
  Se Movía Sobre Las Aguas //
// Pero Ahora Se Esta Moviendo
  Dentro De Mi Corazón //

31.  Jerusalén
// Jerusalén, Que Bonita Eres
  Calles De Oro, Mar De Cristal //
// Por Esas Calles Yo Voy A Caminar
  Calles De Oro, Mar De Cristal //

32.  Donde Esta Tu Dios
//// Donde, Donde Esta Tu Dios ////
// Mi Dios Esta En Los Cielos
  También En Mi Corazón
  El Tuyo Esta Muerto 
  El Mio Resucitó //

39.  Si Tuvieras Fe
// Si Tuvieras Fe
  Como Un Grano De Mostaza,
  Eso Lo Dice El Señor //
// Tu Le Dirías, A Esa Montaña
  Muevete, Muevete //
// Y Esa Montaña Se Moverá
  Se Moverá, Se Moverá //
// Jesus Te Ayudara,
Y La Montaña Se Moverá //

61.  Amemonos De Corazón
// Amemonos De Corazón
   No De Labios Solamente //
// Para Cuando Cristo Venga
   Para Cuando Cristo Venga
  Nos Encuentre Bien Unidos
// Como Puedes Tu Orar
   Enojado Con Tu Hermano //
// Dios No Escucha La Oración
   Dios No Escucha La Oración
   Si No Estas Reconciliado //
// Cuantas Veces Debo Yo
   Perdonar A Mi Hermano //
//  Setenta Veces Siete
   Setenta Veces Siete
  Perdonaras A Tu Hermano //

84.  Bendecido
// Si Alguien Te Pregunta Por Ahí
   ¿ Como Estas, Como Estas ? //
// Bendecido, Muy Bendecido
   Bendecido Porque 
   Cristo Me Salvo //

102.  Donde Esta El Espíritu
// Donde Esta El Espíritu De Dios
   Hay Libertad, Hay Libertad //
//// Libertad ////
Donde Esta El Espíritu De Dios
Ahí Siempre Hay Libertad

110.  A Que Tu No Sabes
// A Que Tu No Sabes 
   Lo Que En Damasco Paso
   Lo Que Paso, Lo Que Paso //
// Fue El Espíritu Santo
   Fue El Espíritu Santo
   Fue El Espíritu Santo
   Que Sobre Pablo Se Derramo //
// A Que Tu No Sabes
   Lo Que En La Iglesia Paso, Etc. . .
// A Que Tu No Sabes
   Lo Que En Mi Vida Paso, Etc . . .

111.  Yo Vine A Alabar A Dios
// Yo No Se A Lo Que Tu Has Venido
   Pero Yo Vine A Alabar A Dios //
// Yo Vine, Yo Vine, Yo Vine
   A Alabar A Dios //

112.  El Señor Me Lleno De Gozo
// El Señor Me Lleno De Gozo
   Puso Paz En Mi Corazón //
//Puso Paz En Mi Corazón //
El Señor Me Lleno De Gozo
Puso Paz En Mi Corazón
(Coro)
// Pero Que Felicidad
   Pero Que Felicidad
   Cantando Todos En Coro 
   A Nuestro Padre Celestial //
// Este Gozo Que Yo Siento En Mi Alma
   Solo Cristo Me Lo Pudo Dar //
// Solo Cristo Me Lo Pudo Dar //
Este Gozo Que Yo Siento En Mi Alma
Solo Cristo Me Lo Pudo Dar   (Coro)
// Fiel Yo Quiero Ser A Jesucristo
   En Las Pruebas Y En La Tentación//
// En Las Pruebas Y En La Tentación//
Fiel Yo Quiero Ser A Jesucristo
En Las Pruebas Y En La Tentación(Coro

124.  Seguirte Solo A Ti Señor
/// Seguirte Solo A Ti Señor ///
Y No Mirar Atrás
// Seguir Tu Caminar, Señor
   Seguir Sin Desmayar, Señor
   Postrado Ante Tu Altar, Señor
   Y No Mirar Atrás //
/// Amarte Solo A Ti Señor ///
Y No Mirar Atrás
// Seguir Tu Caminar Señor
   Seguir Sin Desmayar, Señor 
   Postrado Ante Tu Altar, Señor
   Y No Mirar Atrás //

131.  Era La Una De La Madrugada
// Era La Una De La Madrugada
   Y Yo Buscaba El Rostro Del Señor//
// Señor, Señor Ten Compasión De Mi
   Resuelve Mis Problemas
   Que Yo Confio En Ti //

135.  Que Bonito Es
// Que Bonito Es, Que Bonito Es
   Cantarle Al Señor //
// Oh Hermano, Vamos A Cantarle
   Que Bonito Es, Que Bonito Es
   Cantarle Al Señor //
